# Translates Unity's Metal shader programs (MSL generated by HLSLcc) to HLSL
# for Shader Model 5.
#
# HLSLcc output is very regular: one entry point (xlatMtlMain), structs for
# stage input/output and for each constant buffer, flat statements on
# u_xlat* temporaries. The function body is kept as written; only intrinsics,
# texture methods and constant buffer prefixes are rewritten. Metal's in/out
# structs stay as plain local structs, and generated wrappers copy between
# them and the HLSL signature structs, so varyings can be widened to a layout
# shared by every variant of a pass (D3D11 links stages by register order,
# Metal by name).
import re

SCALAR_SIZE = {"float": 4, "half": 4, "int": 4, "uint": 4, "bool": 4, "short": 4, "ushort": 4}
TEXTURE_HLSL = {
    "texture2d": "Texture2D", "texture3d": "Texture3D", "texturecube": "TextureCube",
    "texture2d_array": "Texture2DArray", "texturecube_array": "TextureCubeArray",
    "depth2d": "Texture2D", "depth2d_array": "Texture2DArray", "depthcube": "TextureCube",
}


class Unsupported(Exception):
    pass


def split_type(t):
    """'float3' -> ('float', 3); 'half' -> ('float', 1)."""
    m = re.fullmatch(r"(float|half|int|uint|bool|short|ushort)([1-4]?)", t)
    if not m:
        raise Unsupported(f"type {t}")
    base = {"half": "float", "short": "int", "ushort": "uint"}.get(m.group(1), m.group(1))
    return base, int(m.group(2) or 1)


def hlsl_type(base, n):
    return base if n == 1 else f"{base}{n}"


# ---------------------------------------------------------------- parsing

class Member:
    def __init__(self, type_, name, array, attr):
        self.type, self.name, self.array, self.attr = type_, name, array, attr


class MslProgram:
    def __init__(self):
        self.stage = None
        self.structs = {}      # name -> [Member]
        self.globals = []      # top-level constant arrays etc., already HLSL
        self.ret_type = None
        self.params = []       # (type, name, attr)
        self.body = ""


def parse_members(text):
    members = []
    for decl in text.split(";"):
        decl = decl.strip()
        if not decl:
            continue
        attrs = [a.strip() for a in re.findall(r"\[\[(.*?)\]\]", decl)]
        decl = re.sub(r"\[\[.*?\]\]", "", decl).strip()
        flat = "flat" in attrs
        attrs = [a for a in attrs if a != "flat"]
        attr = attrs[0] if attrs else None
        m = re.fullmatch(r"([\w:<>, ]+?)\s+(\w+)\s*(?:\[\s*(\d+)\s*\])?", decl)
        if not m:
            raise Unsupported(f"member {decl!r}")
        mb = Member(m.group(1).strip(), m.group(2), int(m.group(3)) if m.group(3) else 0, attr)
        mb.flat = flat
        members.append(mb)
    return members


def parse(msl):
    p = MslProgram()
    text = msl
    # drop the preamble HLSLcc always emits
    text = re.sub(r"#include <[^>]*>\n", "", text)
    text = text.replace("using namespace metal;", "")
    text = re.sub(r"#if !\(__HAVE_FMA__\)\n#define fma\(a,b,c\) \(\(a\) \* \(b\) \+ \(c\)\)\n#endif", "", text)
    text = re.sub(r"#ifndef (\w+)\n\s*#define \1 [^\n]*\n#endif", "", text)
    text = re.sub(r"constexpr constant uint xlt_remap_\w+\[\] = \w+;", "", text)
    for m in re.finditer(r"struct (\w+)\s*\{(.*?)\};", text, re.S):
        p.structs[m.group(1)] = parse_members(m.group(2))
    text = re.sub(r"struct (\w+)\s*\{(.*?)\};", "", text, flags=re.S)
    m = re.search(r"\b(vertex|fragment)\s+(\w+)\s+xlatMtlMain\s*\(", text)
    if not m:
        raise Unsupported("no entry point")
    p.stage, p.ret_type = m.group(1), m.group(2)
    head = text[:m.start()]
    for g in re.finditer(r"constant\s+([\w]+)\s+(\w+)\s*\[\s*(\d+)\s*\]\s*=\s*(\{.*?\});", head, re.S):
        p.globals.append(f"static const {g.group(1)} {g.group(2)}[{g.group(3)}] = {g.group(4)};")
    if re.search(r"\bconstexpr\s+sampler\b", head):
        raise Unsupported("inline sampler")
    # parameter list: balanced parentheses
    i = m.end()
    depth, j = 1, i
    while depth:
        depth += {"(": 1, ")": -1}.get(text[j], 0)
        j += 1
    for prm in split_args(text[i:j - 1]):
        a = re.search(r"\[\[(.*?)\]\]", prm)
        attr = a.group(1).strip() if a else None
        decl = re.sub(r"\[\[.*?\]\]", "", prm).strip()
        mm = re.fullmatch(r"(.+?)\s*([&*]?)\s*(\w+)", decl, re.S)
        if not mm:
            raise Unsupported(f"param {prm!r}")
        p.params.append((mm.group(1).strip() + mm.group(2), mm.group(3), attr))
    b0 = text.index("{", j)
    depth, k = 1, b0 + 1
    while depth:
        depth += {"{": 1, "}": -1}.get(text[k], 0)
        k += 1
    p.body = text[b0 + 1:k - 1]
    return p


def split_args(s):
    out, depth, cur = [], 0, []
    for ch in s:
        if ch in "([<":
            depth += 1
        elif ch in ")]>":
            depth -= 1
        if ch == "," and depth == 0:
            out.append("".join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    if "".join(cur).strip():
        out.append("".join(cur).strip())
    return out


# ------------------------------------------------------- body rewriting

def rewrite_calls(text, name, fn):
    """Replaces every call name(args) (name may include a '.method' suffix
    pattern) with fn(prefix, args)."""
    out, pos = [], 0
    pat = re.compile(name)
    while True:
        m = pat.search(text, pos)
        if not m:
            out.append(text[pos:])
            return "".join(out)
        i = m.end()
        depth, j = 1, i
        while depth:
            depth += {"(": 1, ")": -1}.get(text[j], 0)
            j += 1
        args = split_args(text[i:j - 1])
        out.append(text[pos:m.start()])
        out.append(fn(m, [rewrite_all(a) for a in args]))
        pos = j


def rewrite_texture_call(m, args, tex_kinds):
    tex, method = m.group(1), m.group(2)
    kind = tex_kinds.get(tex, "texture2d")
    is_array = kind.endswith("_array")
    extra = {}
    plain = []
    for a in args:
        mm = re.fullmatch(r"(level|bias|gradient2d|min_lod_clamp)\((.*)\)", a, re.S)
        if mm:
            extra[mm.group(1)] = split_args(mm.group(2))
        else:
            plain.append(a)
    if method == "read":
        coord = plain[0]
        lod = plain[1] if len(plain) > 1 else "0"
        return f"{tex}.Load(int3(int2({coord}), int({lod})))"
    sampler, coord = plain[0], plain[1]
    rest = plain[2:]
    if is_array:
        coord = f"float3({coord}, {rest[0]})" if kind == "texture2d_array" or kind == "depth2d_array" else f"float4({coord}, {rest[0]})"
        rest = rest[1:]
    if method == "sample_compare":
        ref = rest[0]
        offs = rest[1:]
        fn = "SampleCmpLevelZero" if "level" in extra else "SampleCmp"
        return f"{tex}.{fn}({', '.join([sampler, coord, ref] + offs)})"
    offs = rest
    if "level" in extra:
        return f"{tex}.SampleLevel({', '.join([sampler, coord, extra['level'][0]] + offs)})"
    if "bias" in extra:
        return f"{tex}.SampleBias({', '.join([sampler, coord, extra['bias'][0]] + offs)})"
    if "gradient2d" in extra:
        return f"{tex}.SampleGrad({', '.join([sampler, coord] + extra['gradient2d'] + offs)})"
    return f"{tex}.Sample({', '.join([sampler, coord] + offs)})"


_tex_kinds = {}


def vector_ctor(m, args):
    t = m.group(0)[:-1]
    if len(args) == 1:
        return f"(({t})({args[0]}))"  # Metal broadcasts a scalar; an HLSL cast does too
    return f"{t}({', '.join(args)})"


def rewrite_all(text):
    text = rewrite_calls(text, r"\b(?:float|int|uint|bool)[234]\(", vector_ctor)
    text = rewrite_calls(text, r"\bselect\(", lambda m, a: f"(({a[2]}) ? ({a[1]}) : ({a[0]}))")
    text = rewrite_calls(text, r"\b(\w+)\.(sample_compare|sample|read)\(",
                         lambda m, a: rewrite_texture_call(m, a, _tex_kinds))
    return text


def rewrite_body(body, cbuffer_names, tex_kinds):
    global _tex_kinds
    _tex_kinds = tex_kinds
    b = body
    for cb in cbuffer_names:
        b = re.sub(rf"\b{cb}\.", "", b)
    b = re.sub(r"\bfma\(", "mad(", b)
    b = re.sub(r"\bfract\(", "frac(", b)
    b = re.sub(r"\brint\(", "round(", b)
    b = re.sub(r"\bdfdx\(", "ddx(", b)
    b = re.sub(r"\bdfdy\(", "ddy(", b)
    b = re.sub(r"\bdiscard_fragment\(\)", "discard", b)
    b = re.sub(r"\bas_type<(float|uint|int)\d?>\(", lambda m: f"as{m.group(1)}(", b)
    b = re.sub(r"\bvec<(\w+),\s*(\d)>", r"\1\2", b)
    b = re.sub(r"\bhalf(\d?)\b", r"float\1", b)
    b = re.sub(r"\b(short|ushort)(\d?)\b", lambda m: ("int" if m.group(1) == "short" else "uint") + m.group(2), b)
    b = re.sub(r"(\d)h\b", r"\1", b)
    # inline (shadow comparison) samplers become globals bound by the caller
    inline = re.findall(r"constexpr\s+sampler\s+(\w+)\s*\(.*?\);", b, re.S)
    b = re.sub(r"constexpr\s+sampler\s+(\w+)\s*\(.*?\);", "", b, flags=re.S)
    rewrite_body.inline_samplers = inline
    if re.search(r"\b(thread|device|threadgroup)\b", b):
        raise Unsupported("address space qualifier in body")
    return rewrite_all(b)


# ------------------------------------------------------- layout and emit

def cbuffer_layout(members):
    """The Metal layout of a constant buffer, which is what Unity fills (the
    offsets in the shader's parameter tables): returns ([(member, offset)], size).
    Metal aligns float2 to 8 and float3/float4 to 16 (float3 takes 16 bytes);
    array elements are padded to their alignment."""
    out, cur = [], 0
    for mb in members:
        base, n = split_type(mb.type)
        size = {1: 4, 2: 8, 3: 16, 4: 16}[n]
        cur = (cur + size - 1) & ~(size - 1)
        out.append((mb, cur))
        cur += size * (mb.array or 1)
    return out, (cur + 15) & ~15


def packed_array_name(name):
    return name + "__packed"


def rewrite_packed_arrays(text, names):
    """`a[i]` -> `a__packed[(i) >> 2][(i) & 3]` for float arrays, whose Metal
    stride (4 bytes) HLSL constant buffers cannot express."""
    for name in names:
        out, pos = [], 0
        pat = re.compile(rf"\b{name}\[")
        while True:
            m = pat.search(text, pos)
            if not m:
                break
            depth, j = 1, m.end()
            while depth:
                depth += {"[": 1, "]": -1}.get(text[j], 0)
                j += 1
            idx = text[m.end():j - 1]
            out.append(text[pos:m.start()])
            out.append(f"{packed_array_name(name)}({idx})")
            pos = j
        out.append(text[pos:])
        text = "".join(out)
    return text


def semantic_of_attribute(name):
    m = re.fullmatch(r"([A-Z_]+?)(\d*)", name)
    if not m:
        raise Unsupported(f"attribute name {name}")
    return m.group(1) + (m.group(2) or "0")


# D3D11 vertex component for an input semantic (Unity's VertexComponent).
def vertex_component(semantic):
    m = re.fullmatch(r"([A-Z]+)(\d+)", semantic)
    name, idx = m.group(1), int(m.group(2))
    if name == "POSITION":
        return 0
    if name == "NORMAL":
        return 1
    if name == "TANGENT":
        return 2
    if name == "COLOR":
        return 3
    if name == "TEXCOORD":
        return 5 + idx
    raise Unsupported(f"vertex semantic {semantic}")


def varyings_of(prog):
    """Varyings of a program: {semantic: (base, components, interpolation)}."""
    if prog.stage == "vertex":
        struct = prog.structs[prog.ret_type]
    else:
        struct = next((prog.structs[t] for t, n, a in prog.params if a == "stage_in"), [])
    out = {}
    for mb in struct:
        if mb.attr and mb.attr.startswith("user("):
            sem = mb.attr[5:-1].strip()
            base, n = split_type(mb.type)
            out[sem] = (base, n, "flat" if base in ("int", "uint") or getattr(mb, "flat", False) else "linear")
    return out


def union_varyings(progs):
    union = {}
    for p in progs:
        for sem, (base, n, interp) in varyings_of(p).items():
            if sem in union:
                b0, n0, i0 = union[sem]
                if b0 != base:
                    raise Unsupported(f"varying {sem} changes type between variants")
                union[sem] = (base, max(n, n0), i0)
            else:
                union[sem] = (base, n, interp)
    return sorted(union.items())


def swz(n):
    return "xyzw"[:n]


def emit(prog, varyings):
    """HLSL source plus the information needed to rebuild Unity's bindings:
    {'hlsl', 'cbuffers': [(name, register, [(param name, offset)], size)],
     'textures': [(name, t, s, kind)], 'inputs': [(attribute index, semantic)]}."""
    out = []
    info = {"cbuffers": [], "textures": [], "samplers": {}, "inputs": []}
    cb_names, tex_kinds = [], {}
    params_hlsl = []
    packed = []
    for t, name, attr in prog.params:
        if t.endswith("&") and t.startswith("constant "):
            st = t[len("constant "):-1].strip()
            # the register is the Metal buffer slot, which Unity's bindings name
            b_reg = int(re.search(r"buffer\s*\((\d+)\)", attr).group(1))
            layout, size = cbuffer_layout(prog.structs[st])
            lines = [f"cbuffer {name} : register(b{b_reg})", "{"]
            array_helpers = []
            for mb, off in layout:
                base, n = split_type(mb.type)
                comp = "xyzw"[(off % 16) // 4]
                if mb.array and n == 1:
                    scalar = hlsl_type(base, 1)
                    fname = packed_array_name(mb.name)
                    cases = []
                    for index in range(mb.array):
                        offset = off + index * 4
                        var = f"{fname}_{index}"
                        component = "xyzw"[(offset % 16) // 4]
                        lines.append(f"    {scalar} {var} : packoffset(c{offset // 16}.{component});")
                        cases.append(f"case {index}: return {var};")
                    array_helpers.append(f"{scalar} {fname}(int index) {{ switch (index) {{ " + " ".join(cases) + f" default: return {scalar}(0); }} }}")
                    packed.append(mb.name)
                    continue
                if mb.array and n == 2:
                    raise Unsupported("float2 array in a constant buffer")
                arr = f"[{mb.array}]" if mb.array else ""
                lines.append(f"    {hlsl_type(base, n)} {mb.name}{arr} : packoffset(c{off // 16}.{comp});")
            lines.append("};")
            out.extend(lines)
            out.extend(array_helpers)
            info["cbuffers"].append((name, b_reg, [(mb.name, off) for mb, off in layout], size))
            cb_names.append(name)
        elif t.endswith("*"):
            raise Unsupported("buffer pointer parameter (instancing / structured buffer)")
        elif t == "sampler":
            s = int(re.search(r"sampler\s*\((\d+)\)", attr).group(1))
            out.append(f"SamplerState {name} : register(s{s});")
            info["samplers"][name] = s
        elif attr and attr.startswith("texture"):
            mm = re.fullmatch(r"(\w+)<\s*(\w+)\s*,.*>", t)
            kind = mm.group(1)
            if kind not in TEXTURE_HLSL:
                raise Unsupported(f"texture type {kind}")
            tex_kinds[name] = kind
            treg = int(re.search(r"texture\s*\((\d+)\)", attr).group(1))
            elem = "float" if kind.startswith("depth") else "float4"
            out.append(f"{TEXTURE_HLSL[kind]}<{elem}> {name} : register(t{treg});")
            info["textures"].append((name, treg, kind))
        elif attr == "stage_in":
            pass
        elif attr == "position" and prog.stage == "fragment":
            params_hlsl.append((t, name, attr))
        elif attr in ("instance_id", "base_instance", "front_facing", "vertex_id"):
            params_hlsl.append((t, name, attr))
        else:
            raise Unsupported(f"parameter {t} {name} [[{attr}]]")
    out.extend(prog.globals)

    # Metal structs as plain locals
    for sname, members in prog.structs.items():
        if any(sname == t[len("constant "):-1].strip() for t, n, a in prog.params if t.startswith("constant ")):
            continue
        out.append(f"struct {sname}")
        out.append("{")
        for mb in members:
            base, n = split_type(mb.type)
            arr = f"[{mb.array}]" if mb.array else ""
            out.append(f"    {hlsl_type(base, n)} {mb.name}{arr};")
        out.append("};")

    stage_in = next(((t, n) for t, n, a in prog.params if a == "stage_in"), None)
    sys_params = []
    for t, name, attr in params_hlsl:
        sem = {"instance_id": "SV_InstanceID", "vertex_id": "SV_VertexID", "front_facing": "SV_IsFrontFace"}.get(attr)
        if attr == "base_instance":
            out.append(f"static const uint {name} = 0;")
        elif attr == "position":
            pass  # read from hlsl_in.hlsl_position below
        else:
            sys_params.append(f"{'bool' if attr == 'front_facing' else 'uint'} {name} : {sem}")

    body = rewrite_packed_arrays(rewrite_body(prog.body, cb_names, tex_kinds), packed)
    compare = set(re.findall(r"\.sample_compare\(\s*(\w+)", prog.body))
    # Inline samplers are not bound by Unity; with nothing bound, D3D11 samples
    # linear/clamp, which is what Unity's inline samplers ask for.
    for i, name in enumerate(rewrite_body.inline_samplers):
        reg = 15 - i
        out.insert(0, f"SamplerState {name} : register(s{reg});")
    out[:] = [re.sub(r"^SamplerState (\w+)", lambda m: ("SamplerComparisonState " if m.group(1) in compare else "SamplerState ") + m.group(1), l) for l in out]

    if prog.stage == "vertex":
        vin = prog.structs[stage_in[0]] if stage_in else []
        out.append("struct HlslVertexIn")
        out.append("{")
        for mb in vin:
            idx = int(re.search(r"attribute\((\d+)\)", mb.attr).group(1))
            sem = semantic_of_attribute(mb.name)
            base, n = split_type(mb.type)
            out.append(f"    {hlsl_type(base, n)} {mb.name} : {sem};")
            info["inputs"].append((idx, sem))
        out.append("};")
        vout = prog.structs[prog.ret_type]
        pos = next(mb for mb in vout if mb.attr == "position")
        out.append("struct HlslVertexOut")
        out.append("{")
        out.append(f"    float4 {pos.name} : SV_Position;")
        for sem, (base, n, interp) in varyings:
            q = "nointerpolation " if interp == "flat" else ""
            out.append(f"    {q}{hlsl_type(base, n)} {sem}_v : {sem};")
        out.append("};")
        out.append(f"HlslVertexOut HlslPack({prog.ret_type} o)")
        out.append("{")
        out.append("    HlslVertexOut r = (HlslVertexOut)0;")
        out.append(f"    r.{pos.name} = o.{pos.name};")
        by_sem = {mb.attr[5:-1].strip(): mb for mb in vout if mb.attr and mb.attr.startswith("user(")}
        for sem, (base, n, interp) in varyings:
            if sem in by_sem:
                m_n = split_type(by_sem[sem].type)[1]
                out.append(f"    r.{sem}_v.{swz(m_n)} = o.{by_sem[sem].name};")
        out.append("    return r;")
        out.append("}")
        body = re.sub(r"\breturn\s+output\s*;", "return HlslPack(output);", body)
        args = []
        if stage_in:
            args.append("HlslVertexIn hlsl_in")
            body = f"    {stage_in[0]} {stage_in[1]};\n" + "".join(
                f"    {stage_in[1]}.{mb.name} = hlsl_in.{mb.name};\n" for mb in vin) + body
        args += sys_params
        out.append(f"HlslVertexOut main({', '.join(args)})")
    else:
        fin_t, fin_n = stage_in if stage_in else (None, None)
        fin = prog.structs[fin_t] if fin_t else []
        pos = next((mb for mb in fin if mb.attr == "position"), None)
        out.append("struct HlslFragmentIn")
        out.append("{")
        out.append("    float4 hlsl_position : SV_Position;")
        for sem, (base, n, interp) in varyings:
            q = "nointerpolation " if interp == "flat" else ""
            out.append(f"    {q}{hlsl_type(base, n)} {sem}_v : {sem};")
        out.append("};")
        fout = prog.structs[prog.ret_type]
        out.append("struct HlslFragmentOut")
        out.append("{")
        for mb in fout:
            mm = re.match(r"color\((?:xlt_remap_o\[)?(\d+)", mb.attr or "")
            if mm:
                sem = f"SV_Target{mm.group(1)}"
            elif (mb.attr or "").startswith("depth"):
                sem = "SV_Depth"
            else:
                raise Unsupported(f"fragment output [[{mb.attr}]]")
            base, n = split_type(mb.type)
            out.append(f"    {hlsl_type(base, n)} {mb.name} : {sem};")
        out.append("};")
        out.append(f"HlslFragmentOut HlslPack({prog.ret_type} o)")
        out.append("{")
        out.append("    HlslFragmentOut r;")
        for mb in fout:
            out.append(f"    r.{mb.name} = o.{mb.name};")
        out.append("    return r;")
        out.append("}")
        body = re.sub(r"\breturn\s+output\s*;", "return HlslPack(output);", body)
        pre = ""
        if fin_t:
            pre += f"    {fin_t} {fin_n};\n"
            for mb in fin:
                if mb.attr == "position":
                    pre += f"    {fin_n}.{mb.name} = hlsl_in.hlsl_position;\n"
                elif mb.attr and mb.attr.startswith("user("):
                    sem = mb.attr[5:-1].strip()
                    n = split_type(mb.type)[1]
                    pre += f"    {fin_n}.{mb.name} = hlsl_in.{sem}_v.{swz(n)};\n"
                else:
                    raise Unsupported(f"fragment input [[{mb.attr}]]")
        for t, name, attr in params_hlsl:
            if attr == "position":
                pre += f"    float4 {name} = hlsl_in.hlsl_position;\n"
        body = pre + body
        args = ["HlslFragmentIn hlsl_in"] + sys_params
        out.append(f"HlslFragmentOut main({', '.join(args)})")
    out.append("{")
    out.append(body)
    out.append("}")
    info["hlsl"] = "\n".join(out) + "\n"
    return info
